import fs from 'node:fs';
import path from 'node:path';
import { parse, stringify } from 'yaml';

const ROLES = ['adventurer', 'architect', 'builder', 'diagnose', 'planner', 'reviewer', 'writer'];
const MODES = ['blitz', 'fein', 'sonar'];
const SHARED_SKILLS = [
  ...ROLES,
  ...MODES,
  'orchestrator',
  'global-rules',
  'handoff',
  'iteration-limits',
];
const NOTICE =
  '<!-- Generated by scripts/sync-consolidated-plugin.ts. Edit its inputs and regenerate. -->';
const HOST_LIMIT =
  'Live host loading is unverified. Package and sync checks validate the shipped files, not runtime discovery or enforcement.';
const VERIFIED_HOST_LIMITS: Record<string, string> = {
  'claude-code':
    'Claude Code 2.1.217 native reviewer dispatch, shared skill preloading, and Write/Edit tool-schema exclusion passed an offline fixture probe. This does not evaluate model judgment, every specialist, shell-mediated editing, or other host versions. See the repository host-verification record for reproduction and limits.',
  hermes:
    'Portable plugin doctor and isolated packed-skill discovery were verified during consolidation. End-to-end task behavior, delegation, and runtime enforcement remain unverified.',
  omp: 'OMP 18.4.8 installed-loader and capability-provider discovery passed against a packed archive in a manually constructed npm-layout fixture. The npm installation transaction, live session/task execution, permissions, and enforcement remain unverified. See the repository host-verification record for reproduction and limits.',
};
